8	static void show_usage(FAR const char *progname)
9	{
10	  printf("Usage: %s [test]\n", progname);
11	  printf("  test options:\n");
12	  printf("    led       - Test LED (GPIO%d, active-low)\n", LED_GPIO_PIN);
13	  printf("    oled      - Test SSD1306 OLED (I2C1, addr=0x3C)\n");
14	  printf("    key       - Test Key (GPIO%d)\n", KEY_GPIO_PIN);
15	  printf("    thermal   - Test thermal sensor\n");
16	  printf("    pwm       - Test PWM controller\n");
17	  printf("    watchdog  - Test watchdog timer\n");
18	  printf("    rtc       - Test RTC (real-time clock)\n");
19	  printf("    adc       - Test ADC (analog-to-digital)\n");
20	  printf("    all       - Run all tests (default)\n");
21	}
