133	
134	static inline uint32_t i2c_getreg(struct ls2k300_i2c_priv_s *priv,
135	                                  uint32_t offset)
136	{
137	  return getreg32(priv->base + offset);
138	}
139	
140	static inline void i2c_putreg(struct ls2k300_i2c_priv_s *priv,
141	                              uint32_t offset, uint32_t value)
142	{
143	  putreg32(value, priv->base + offset);
144	}
145	
146	static void i2c_set_bits(struct ls2k300_i2c_priv_s *priv,
147	                         uint32_t offset, uint32_t mask)
148	{
149	  uint32_t regval = i2c_getreg(priv, offset);
150	  regval |= mask;
151	  i2c_putreg(priv, offset, regval);
152	}
153	
154	static void i2c_clr_bits(struct ls2k300_i2c_priv_s *priv,
155	                         uint32_t offset, uint32_t mask)
156	{
157	  uint32_t regval = i2c_getreg(priv, offset);
158	  regval &= ~mask;
159	  i2c_putreg(priv, offset, regval);
160	}
161	
162	static void ls2k300_i2c_hw_config(struct ls2k300_i2c_priv_s *priv)
163	{
164	  uint32_t val;
165	  uint32_t ccr = 0;
166	
167	  i2c_set_bits(priv, LS2K300_I2C_CR2, I2C_CR2_FREQ_MASK);
168	  i2c_set_bits(priv, LS2K300_I2C_TRISE, I2C_CR2_FREQ_MASK);
169	
170	  if (priv->frequency <= I2C_SPEED_STANDARD)
171	    {
172	      val = (LS2K300_I2C_INPUT_CLK + 100000 * 2 - 1) / (100000 * 2);
173	    }
174	  else
175	    {
176	      val = (LS2K300_I2C_INPUT_CLK + 400000 * 3 - 1) / (400000 * 3);
177	      ccr |= I2C_CCR_FS;
178	    }
179	
180	  ccr |= val & 0xfff;
181	  i2c_putreg(priv, LS2K300_I2C_CCR, ccr);
182	
183	  i2c_putreg(priv, LS2K300_I2C_CR1, I2C_CR1_PE);
184	}
185	
186	static int ls2k300_i2c_wait_status(struct ls2k300_i2c_priv_s *priv,
187	                                   uint32_t mask, bool set,
188	                                   uint32_t timeout_us)
189	{
190	  uint32_t elapsed = 0;
191	  uint32_t status;
192	
193	  while (elapsed < timeout_us)
194	    {
195	      status = i2c_getreg(priv, LS2K300_I2C_SR1);
196	
197	      if (set && (status & mask))
198	        {
199	          return OK;
200	        }
201	
202	      if (!set && !(status & mask))
203	        {
204	          return OK;
205	        }
206	
207	      up_udelay(10);
208	      elapsed += 10;
209	    }
210	
211	  return -ETIMEDOUT;
212	}
213	
214	static int ls2k300_i2c_wait_free_bus(struct ls2k300_i2c_priv_s *priv)
215	{
216	  uint32_t elapsed = 0;
217	  uint32_t status;
218	
219	  while (elapsed < LS2K300_I2C_TIMEOUT_US)
220	    {
221	      status = i2c_getreg(priv, LS2K300_I2C_SR2);
222	      if (!(status & I2C_SR2_BUSY))
223	        {
224	          return OK;
225	        }
226	
227	      up_udelay(10);
228	      elapsed += 10;
229	    }
230	
231	  return -EBUSY;
232	}
233	
234	static void ls2k300_i2c_clear_addr(struct ls2k300_i2c_priv_s *priv)
235	{
236	  i2c_getreg(priv, LS2K300_I2C_SR1);
237	  i2c_getreg(priv, LS2K300_I2C_SR2);
238	}
239	
240	static int ls2k300_i2c_check_errors(struct ls2k300_i2c_priv_s *priv,
241	                                    uint32_t status)
242	{
243	  if (status & I2C_SR1_ARLO)
244	    {
245	      i2c_clr_bits(priv, LS2K300_I2C_SR1, I2C_SR1_ARLO);
246	      return -EAGAIN;
247	    }
248	
249	  if (status & I2C_SR1_AF)
250	    {
251	      i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
252	      i2c_clr_bits(priv, LS2K300_I2C_SR1, I2C_SR1_AF);
253	      return -EIO;
254	    }
255	
256	  if (status & I2C_SR1_BERR)
257	    {
258	      i2c_clr_bits(priv, LS2K300_I2C_SR1, I2C_SR1_BERR);
259	      return -EIO;
260	    }
261	
262	  return OK;
263	}
264	
265	static int ls2k300_i2c_send_addr(struct ls2k300_i2c_priv_s *priv,
266	                                 struct i2c_msg_s *msg)
267	{
268	  uint8_t addr;
269	  int ret;
270	
271	  ret = ls2k300_i2c_wait_status(priv, I2C_SR1_SB, true,
272	                                 LS2K300_I2C_TIMEOUT_US);
273	  if (ret < 0)
274	    {
275	      return ret;
276	    }
277	
278	  if (msg->flags & I2C_M_READ)
279	    {
280	      addr = I2C_READADDR8(msg->addr);
281	    }
282	  else
283	    {
284	      addr = I2C_WRITEADDR8(msg->addr);
285	    }
286	
287	  i2c_putreg(priv, LS2K300_I2C_DR, addr);
288	
289	  ret = ls2k300_i2c_wait_status(priv, I2C_SR1_ADDR, true,
290	                                 LS2K300_I2C_TIMEOUT_US);
291	  if (ret < 0)
292	    {
293	      uint32_t sr1 = i2c_getreg(priv, LS2K300_I2C_SR1);
294	      int err = ls2k300_i2c_check_errors(priv, sr1);
295	      return err < 0 ? err : ret;
296	    }
297	
298	  return OK;
299	}
300	
301	static int ls2k300_i2c_read(struct ls2k300_i2c_priv_s *priv,
302	                            struct i2c_msg_s *msg, bool is_last)
303	{
304	  uint32_t count = msg->length;
305	  FAR uint8_t *buf = msg->buffer;
306	  int ret;
307	
308	  if (count == 0)
309	    {
310	      if (is_last)
311	        {
312	          i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
313	        }
314	
315	      ls2k300_i2c_clear_addr(priv);
316	      return OK;
317	    }
318	
319	  if (count == 1)
320	    {
321	      i2c_clr_bits(priv, LS2K300_I2C_CR1, I2C_CR1_ACK | I2C_CR1_POS);
322	
323	      ls2k300_i2c_clear_addr(priv);
324	
325	      if (is_last)
326	        {
327	          i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
328	        }
329	
330	      ret = ls2k300_i2c_wait_status(priv, I2C_SR1_RXNE, true,
331	                                     LS2K300_I2C_TIMEOUT_US);
332	      if (ret < 0)
333	        {
334	          return ret;
335	        }
336	
337	      *buf = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
338	      return OK;
339	    }
340	
341	  if (count == 2)
342	    {
343	      i2c_clr_bits(priv, LS2K300_I2C_CR1, I2C_CR1_ACK);
344	      i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_POS);
345	
346	      ls2k300_i2c_clear_addr(priv);
347	
348	      while (!(i2c_getreg(priv, LS2K300_I2C_SR1) & I2C_SR1_BTF))
349	        ;
350	
351	      if (is_last)
352	        {
353	          i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
354	        }
355	
356	      i2c_clr_bits(priv, LS2K300_I2C_CR1, I2C_CR1_POS);
357	
358	      *buf++ = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
359	      *buf   = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
360	      return OK;
361	    }
362	
363	  i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_ACK);
364	  i2c_clr_bits(priv, LS2K300_I2C_CR1, I2C_CR1_POS);
365	
366	  ls2k300_i2c_clear_addr(priv);
367	
368	  while (count > 3)
369	    {
370	      ret = ls2k300_i2c_wait_status(priv, I2C_SR1_BTF, true,
371	                                     LS2K300_I2C_TIMEOUT_US);
372	      if (ret < 0)
373	        {
374	          return ret;
375	        }
376	
377	      *buf++ = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
378	      count--;
379	    }
380	
381	  ret = ls2k300_i2c_wait_status(priv, I2C_SR1_BTF, true,
382	                                 LS2K300_I2C_TIMEOUT_US);
383	  if (ret < 0)
384	    {
385	      return ret;
386	    }
387	
388	  i2c_clr_bits(priv, LS2K300_I2C_CR1, I2C_CR1_ACK);
389	
390	  (void)i2c_getreg(priv, LS2K300_I2C_SR1);
391	
392	  if (is_last)
393	    {
394	      i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
395	    }
396	
397	  *buf++ = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
398	  *buf++ = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
399	  count -= 2;
400	
401	  while (count > 0)
402	    {
403	      ret = ls2k300_i2c_wait_status(priv, I2C_SR1_RXNE, true,
404	                                     LS2K300_I2C_TIMEOUT_US);
405	      if (ret < 0)
406	        {
407	          return ret;
408	        }
409	
410	      *buf++ = (uint8_t)i2c_getreg(priv, LS2K300_I2C_DR);
411	      count--;
412	    }
413	
414	  return OK;
415	}
416	
417	static int ls2k300_i2c_write(struct ls2k300_i2c_priv_s *priv,
418	                             struct i2c_msg_s *msg, bool is_last)
419	{
420	  uint32_t count = msg->length;
421	  FAR uint8_t *buf = msg->buffer;
422	  int ret;
423	  uint32_t sr1;
424	
425	  ls2k300_i2c_clear_addr(priv);
426	
427	  while (count > 0)
428	    {
429	      i2c_putreg(priv, LS2K300_I2C_DR, *buf++);
430	      count--;
431	
432	      if (count == 0)
433	        {
434	          ret = ls2k300_i2c_wait_status(priv, I2C_SR1_BTF, true,
435	                                         LS2K300_I2C_TIMEOUT_US);
436	          if (ret < 0)
437	            {
438	              return ret;
439	            }
440	
441	          if (is_last)
442	            {
443	              i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
444	            }
445	        }
446	      else
447	        {
448	          ret = ls2k300_i2c_wait_status(priv, I2C_SR1_TXE, true,
449	                                         LS2K300_I2C_TIMEOUT_US);
450	          if (ret < 0)
451	            {
452	              return ret;
453	            }
454	        }
455	
456	      sr1 = i2c_getreg(priv, LS2K300_I2C_SR1);
457	      ret = ls2k300_i2c_check_errors(priv, sr1);
458	      if (ret < 0)
459	        {
460	          return ret;
461	        }
462	    }
463	
464	  return OK;
465	}
466	
467	static int ls2k300_i2c_transfer_msg(struct ls2k300_i2c_priv_s *priv,
468	                                    struct i2c_msg_s *msg, bool is_last)
469	{
470	  int ret;
471	  uint32_t sr1;
472	
473	  i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_START);
474	
475	  ret = ls2k300_i2c_send_addr(priv, msg);
476	  if (ret < 0)
477	    {
478	      i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
479	      return ret;
480	    }
481	
482	  sr1 = i2c_getreg(priv, LS2K300_I2C_SR1);
483	  ret = ls2k300_i2c_check_errors(priv, sr1);
484	  if (ret < 0)
485	    {
486	      i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
487	      return ret;
488	    }
489	
490	  if (msg->flags & I2C_M_READ)
491	    {
492	      ret = ls2k300_i2c_read(priv, msg, is_last);
493	    }
494	  else
495	    {
496	      ret = ls2k300_i2c_write(priv, msg, is_last);
497	    }
498	
499	  if (ret < 0)
500	    {
501	      i2c_set_bits(priv, LS2K300_I2C_CR1, I2C_CR1_STOP);
502	      return ret;
503	    }
504	
505	  return OK;
506	}
507	
508	static int ls2k300_i2c_transfer(struct i2c_master_s *dev,
509	                                struct i2c_msg_s *msgs, int count)
510	{
511	  struct ls2k300_i2c_priv_s *priv =
512	      (struct ls2k300_i2c_priv_s *)dev;
513	  int ret;
514	  int i;
515	
516	  if (count <= 0 || msgs == NULL)
517	    {
518	      return -EINVAL;
519	    }
520	
521	  ret = nxsem_wait(&priv->sem);
522	  if (ret < 0)
523	    {
524	      return ret;
525	    }
526	
527	  if (msgs[0].frequency != priv->frequency)
528	    {
529	      priv->frequency = msgs[0].frequency;
530	      ls2k300_i2c_hw_config(priv);
531	    }
532	
533	  ret = ls2k300_i2c_wait_free_bus(priv);
534	  if (ret < 0)
535	    {
536	      nxsem_post(&priv->sem);
537	      return ret;
538	    }
539	
540	  for (i = 0; i < count; i++)
541	    {
542	      bool is_last = (i == count - 1);
543	
544	      if (msgs[i].flags & I2C_M_NOSTART)
545	        {
546	          continue;
547	        }
548	
549	      ret = ls2k300_i2c_transfer_msg(priv, &msgs[i], is_last);
550	      if (ret < 0)
551	        {
552	          nxsem_post(&priv->sem);
553	          return ret;
554	        }
555	    }
556	
557	  nxsem_post(&priv->sem);
558	  return count;
559	}
