33	static int ls2k300_pinctrl_set_function(FAR struct pinctrl_dev_s *dev,
34	                                        uint32_t pin, uint32_t function)
35	{
36	  FAR struct ls2k300_pinctrl_dev_s *priv =
37	      (FAR struct ls2k300_pinctrl_dev_s *)dev;
38	  uint32_t reg_offset;
39	  uint32_t bit_offset;
40	  uint32_t reg_val;
41	  uint32_t mask;
42	
43	  if (pin >= LS2K300_GPIO_NPINS || function > LS2K300_PINCTRL_FUNC_MASK)
44	    {
45	      return -EINVAL;
46	    }
47	
48	  reg_offset = (pin / PINS_PER_REG) * 4;
49	  bit_offset = (pin % PINS_PER_REG) * 2;
50	
51	  mask = LS2K300_PINCTRL_FUNC_MASK << bit_offset;
52	
53	  reg_val = getreg32(priv->base + reg_offset);
54	  reg_val &= ~mask;
55	  reg_val |= (function & LS2K300_PINCTRL_FUNC_MASK) << bit_offset;
56	  putreg32(reg_val, priv->base + reg_offset);
57	
58	  return OK;
59	}
