static int oled_pinctrl_setup(void)
{
  struct pinctrl_param_s param;
  int fd;
  int ret;

  fd = open("/dev/pinctrl0", O_RDWR);
  if (fd < 0)
    {
      printf("[OLED] ERROR: Failed to open /dev/pinctrl0: %d\n", errno);
      return -errno;
    }

  /* Set GPIO50 (SCL) to ALT1 function (I2C1) */

  param.pin = I2C1_SCL_PIN;
  param.para.function = 1; /* ALT1 = main function */
  ret = ioctl(fd, PINCTRLC_SETFUNCTION, (unsigned long)&param);
  if (ret < 0)
    {
      printf("[OLED] ERROR: PINCTRLC_SETFUNCTION GPIO%d failed: %d\n",
             I2C1_SCL_PIN, errno);
      close(fd);
      return -errno;
    }

  /* Set GPIO51 (SDA) to ALT1 function (I2C1) */

  param.pin = I2C1_SDA_PIN;
  param.para.function = 1; /* ALT1 = main function */
  ret = ioctl(fd, PINCTRLC_SETFUNCTION, (unsigned long)&param);
  if (ret < 0)
    {
      printf("[OLED] ERROR: PINCTRLC_SETFUNCTION GPIO%d failed: %d\n",
             I2C1_SDA_PIN, errno);
      close(fd);
      return -errno;
    }

  close(fd);
  printf("[OLED] Pinctrl: GPIO%d/GPIO%d set to I2C1 function\n",
         I2C1_SCL_PIN, I2C1_SDA_PIN);
  return OK;
}

